tool_input.content:
/* map.js — grade do mapa + lógica pura de grid (LOS, raycast DDA).
 * Puro: NÃO importa Three.js — 100% testável em node.
 * Símbolos:
 *   # parede  . chão  P spawn  D porta (E)  E saída  H saúde  A armadura
 *   m munição  2/3/4 armas  i imp  d demon  B baron  z zombie  x secreto
 *   ~ lava (dano)  L tocha
 */
import { C } from './constants.js';

export const W = C.LEVEL.W;
export const H = C.LEVEL.H;

export const RAW = [
  '############################################',
  '#........#z........i#...........#........d.#',
  '####.###.#..###..####..###.###..#..####..#.#',
  '#..L..#.#..#2....#.....#.....#...#.....#...#',
  '#..H..###..#.###.#..D..###.###.#..H...#...#',
  '#.......P....L..#..i..#............#.......#',
  '#..####..###..D..#######..#.#####.#..###..###',
  '#.....#.....D.....i..#....#.....#.#........#',
  '###.###..###..######.#..###.....#.########.#',
  '#...#.L..z....#....#.#....#..H..#........#.#',
  '#..H.#..####..#.D..#..#####..##.#..#####....#',
  '#....#..#..m..#....#..#....#....#..#....#d.##',
  '#....D..#......#####..####..####..###..#####',
  '#..###..#mmmm#.....#...........#......m..#.#',
  '#.....#..####..##.###..#########..#####...#.#',
  '#..H..D.....i..#.....#.....#.z.......H....#.#',
  '####...#####..##.#####..###..#####....####.#',
  '#...#Ad.....#....#....#.....#.....#..####..#',
  '#...#####..###..#.#..#..m#..A.#..###.....#.#',
  '#.......#.i..m..#.#.#....#....#..#......d#.#',
  '#####..###.#####.##.#.###########.####....#.#',
  '#...D.....3#..L..#..#~~~.........#....#####.#',
  '#...##.####.#.#####.#.###.#####..#.##....#.#',
  '#.........#.#.......#.#.......#..#.#..##..#.#',
  '#.###########.#####.#.#####.#.###.#.######..#',
  '#...#........#.....#d#.....#.....#.......#d.#',
  '#...####..###..####.#..#####..##.#.#######.#',
  '#...#......#...z...#...#........#.....#.....#',
  '#..#####..#####.###.#####..#######.#####..###',
  '#..E..#L....4#.......#......#.....#........#',
  '#####..##..####..####..###..###..######..####',
  '#.........................#..............E...#',
  '#..###..###..###..###..#####..##..####....#',
  '#..#...B....B....B..L.B....#..#........H..x#',
  '#..###..###..###..###..####..##..####....#',
  '############################################',
];

/* Normaliza linhas: padEnd + slice para W, força bordas fechadas. */
export function normalize(rows) {
  const h = rows.length;
  const w = Math.max(...rows.map((r) => r.length));
  const out = rows.map((r) => r.padEnd(w, '#').slice(0, w).split(''));
  for (let c = 0; c < w; c++) { out[0][c] = '#'; out[h - 1][c] = '#'; }
  for (let r = 0; r < h; r++) { out[r][0] = '#'; out[r][w - 1] = '#'; }
  return out.map((row) => row.join(''));
}

/* Zona por região (6): entrada, salao, forja, catacumbas, armadilha, arena. */
export function zone(r, c) {
  if (r >= 28) return 'arena';
  if (r >= 24 && c >= 29) return 'armadilha';
  if (c >= 29) return 'catacumbas';
  if (c >= 18 && c < 29) return 'forja';
  if (c >= 8 && c < 18) return 'salao';
  return 'entrada';
}

/* Cria o estado do mapa (portas/secrets mutáveis). rows opcional p/ testes. */
export function makeMap(rows = RAW) {
  const grid = normalize(rows);
  const h = grid.length;
  const w = grid[0].length;
  const doors = [];
  const secrets = [];
  const exits = [];
  const pickups = [];
  const enemies = [];
  const torches = [];
  let spawn = { x: 1.5, z: 1.5 };

  for (let r = 0; r < h; r++) {
    for (let c = 0; c < w; c++) {
      const ch = grid[r][c];
      const x = c + 0.5, z = r + 0.5;
      if (ch === 'D') doors.push({ r, c, open: false, t: 1 });
      else if (ch === 'x') secrets.push({ r, c, open: false });
      else if (ch === 'E') exits.push({ r, c });
      else if (ch === 'H' || ch === 'A' || ch === 'm' || ch === '2' || ch === '3' || ch === '4') {
        const type = ch === 'H' ? 'health' : ch === 'A' ? 'armor' : ch === 'm' ? 'ammo'
          : ch === '2' ? 'shotgun' : ch === '3' ? 'chaingun' : 'rocket';
        pickups.push({ type, r, c, x, z, taken: false });
      } else if (ch === 'i' || ch === 'd' || ch === 'B' || ch === 'z') {
        const type = ch === 'i' ? 'imp' : ch === 'd' ? 'demon' : ch === 'B' ? 'baron' : 'zombie';
        enemies.push({ type, r, c, x, z });
      } else if (ch === 'P') {
        spawn = { x, z };
      } else if (ch === 'L') {
        torches.push({ r, c, x, z });
      }
    }
  }

  function isSolid(r, c) {
    if (r < 0 || c < 0 || r >= h || c >= w) return true;
    const ch = grid[r][c];
    if (ch === 'D') {
      const d = doors.find((x) => x.r === r && x.c === c);
      return !(d && d.open);
    }
    if (ch === 'x') {
      const s = secrets.find((x) => x.r === r && x.c === c);
      return !(s && s.open);
    }
    return ch === '#';
  }

  function cellType(r, c) {
    if (r < 0 || c < 0 || r >= h || c >= w) return '#';
    return grid[r][c];
  }

  function isLava(r, c) {
    return cellType(r, c) === '~';
  }

  return {
    W: w, H: h, grid, doors, secrets, exits, pickups, enemies, torches, spawn,
    isSolid, cellType, isLava, zone,
  };
}

/* Bresenham em células: LOS entre (r1,c1) e (r2,c2). Retorna true se não há parede. */
export function hasLOS(map, r1, c1, r2, c2) {
  let r = r1, c = c1;
  const dr = Math.abs(r2 - r1);
  const dc = Math.abs(c2 - c1);
  const sr = r1 < r2 ? 1 : -1;
  const sc = c1 < c2 ? 1 : -1;
  let err = dc - dr;
  for (;;) {
    if (map.isSolid(r, c)) return false;
    if (r === r2 && c === c2) return true;
    const e2 = 2 * err;
    if (e2 > -dc) { err -= dr; r += sr; }
    if (e2 < dr) { err += dc; c += sc; }
  }
}

/* Raycast DDA (hitscan): de (ox,oz) na direção (dx,dz). Retorna distância até a parede. */
export function raycastWall(map, ox, oz, dx, dz, maxDist = 800) {
  const deltaX = dx !== 0 ? Math.abs(1 / dx) : Infinity;
  const deltaZ = dz !== 0 ? Math.abs(1 / dz) : Infinity;
  let mapX = Math.floor(ox);
  let mapZ = Math.floor(oz);
  let stepX, stepZ, sideX, sideZ;
  if (dx < 0) { stepX = -1; sideX = (ox - mapX) * deltaX; }
  else { stepX = 1; sideX = (mapX + 1 - ox) * deltaX; }
  if (dz < 0) { stepZ = -1; sideZ = (oz - mapZ) * deltaZ; }
  else { stepZ = 1; sideZ = (mapZ + 1 - oz) * deltaZ; }
  let dist = 0;
  for (let i = 0; i < 2000; i++) {
    if (sideX < sideZ) { dist = sideX; sideX += deltaX; mapX += stepX; }
    else { dist = sideZ; sideZ += deltaZ; mapZ += stepZ; }
    if (dist > maxDist) return maxDist;
    if (map.isSolid(mapZ, mapX)) return dist;
  }
  return maxDist;
}

/* Distância euclidiana 2D. */
export function dist2D(ax, az, bx, bz) {
  return Math.hypot(bx - ax, bz - az);
}

