        const type = ch === 'H' ? 'health' : ch === 'A' ? 'armor' : ch === 'm' ? 'ammo'
          : ch === '2' ? 'shotgun' : ch === '3' ? 'chaingun' : 'rocket';
        pickups.push({ type, r, c, x, z, taken: false });
      } else if (ch === 'i' || ch === 'd' || ch === 'B' || ch === 'z') {
        const type = ch === 'i' ? 'imp' : ch === 'd' ? 'demon' : ch === 'B' ? 'baron' : 'zombie';
        enemies.push({ type, r, c, x, z });
      } else if (ch === 'P') {
        spawn = { x, z };
      } else if (ch === 'L') {
        torches.push({ r, c, x, z });
      }
    }
  }

  function isSolid(r, c) {
    if (r < 0 || c < 0 || r >= h || c >= w) return true;
    const ch = grid[r][c];
    if (ch === 'D') {
      const d = doors.find((x) => x.r === r && x.c === c);
      return !(d && d.open);
    }
    if (ch === 'x') {
      const s = secrets.find((x) => x.r === r && x.c === c);
      return !(s && s.open);
    }
    return ch === '#';
  }

  function cellType(r, c) {
    if (r < 0 || c < 0 || r >= h || c >= w) return '#';
    return grid[r][c];
  }

  function isLava(r, c) {
    return cellType(r, c) === '~';
  }

  return {
    W: w, H: h, grid, doors, secrets, exits, pickups, enemies, torches, spawn,
    isSolid, cellType, isLava, zone,
  };
}

/* Bresenham em células: LOS entre (r1,c1) e (r2,c2). Retorna true se não há parede. */
export function hasLOS(map, r1, c1, r2, c2) {
  let r = r1, c = c1;
  const dr = Math.abs(r2 - r1);
  const dc = Math.abs(c2 - c1);
  const sr = r1 < r2 ? 1 : -1;
  const sc = c1 < c2 ? 1 : -1;
  let err = dc - dr;
  for (;;) {
    if (map.isSolid(r, c)) return false;
    if (r === r2 && c === c2) return true;
    const e2 = 2 * err;
    if (e2 > -dc) { err -= dr; r += sr; }
    if (e2 < dr) { err += dc; c += sc; }
  }
}

/* Raycast DDA (hitscan): de (ox,oz) na direção (dx,dz). Retorna distância até a parede. */
export function raycastWall(map, ox, oz, dx, dz, maxDist = 800) {
  const deltaX = dx !== 0 ? Math.abs(1 / dx) : Infinity;
  const deltaZ = dz !== 0 ? Math.abs(1 / dz) : Infinity;
  let mapX = Math.floor(ox);
  let mapZ = Math.floor(oz);
  let stepX, stepZ, sideX, sideZ;
  if (dx < 0) { stepX = -1; sideX = (ox - mapX) * deltaX; }
  else { stepX = 1; sideX = (mapX + 1 - ox) * deltaX; }
  if (dz < 0) { stepZ = -1; sideZ = (oz - mapZ) * deltaZ; }
  else { stepZ = 1; sideZ = (mapZ + 1 - oz) * deltaZ; }
  let dist = 0;
  for (let i = 0; i < 2000; i++) {
    if (sideX < sideZ) { dist = sideX; sideX += deltaX; mapX += stepX; }
    else { dist = sideZ; sideZ += deltaZ; mapZ += stepZ; }
    if (dist > maxDist) return maxDist;
    if (map.isSolid(mapZ, mapX)) return dist;
  }
  return maxDist;
}

/* Distância euclidiana 2D. */
export function dist2D(ax, az, bx, bz) {
  return Math.hypot(bx - ax, bz - az);
}

/* move.js — transformação de entrada de movimento (local → mundo) + colisão
 * círculo-vs-grade com resolução por eixo. Puro e testável.
 *
 * moveVec: vetor local (ix, iz): +x = direita, +z = trás (convenção câmera).
 * Aplica R_y(yaw) correta:
 *   mundo.x = ix*cos(yaw) + iz*sin(yaw)
 *   mundo.z = -ix*sin(yaw) + iz*cos(yaw)
 */
export function moveVec(yaw, ix, iz) {
  const sy = Math.sin(yaw), cy = Math.cos(yaw);
  return { x: ix * cy + iz * sy, z: -ix * sy + iz * cy };
}

/* True se um círculo de raio `radius` centrado em (x,z) não sobrepõe célula sólida. */
export function circleFree(map, x, z, radius) {
  const r0 = Math.floor(z - radius);
  const r1 = Math.floor(z + radius);
  const c0 = Math.floor(x - radius);
  const c1 = Math.floor(x + radius);
  for (let r = r0; r <= r1; r++) {
    for (let c = c0; c <= c1; c++) {
      if (map.isSolid(r, c)) return false;
    }
  }
  return true;
}

/* Slide por eixo (X primeiro, depois Z): tenta mover para (nx,nz); se o eixo X
 * colide, mantém x original; depois tenta Z a partir do x resolvido. */
export function slideCircle(map, x, z, nx, nz, radius) {
  let rx = nx;
  let rz = nz;
  if (!circleFree(map, nx, z, radius)) rx = x;
  if (!circleFree(map, rx, nz, radius)) rz = z;
  return { x: rx, z: rz };
}

export default { moveVec, circleFree, slideCircle };

