/* physics.js — integração de movimento do jogador (aceleração/atrito/gravidade/
 * pulo) + slide contra a grade. Puro e testável.
 */
import { C } from './constants.js';
import { slideCircle } from './move.js';

/* Um passo de física do jogador.
 * p: { x, y, z, vx, vy, vz, onGround }
 * input: { dx, dz (direção mundo normalizada), mag (0..1), run, jump }
 * Retorna p (mutado) — conveniência para encadeamento.
 */
export function stepPlayer(map, p, input, dt) {
  const P = C.PLAYER;
  const maxSpeed = input.run ? P.run : P.walk;
  const target = maxSpeed * input.mag;

  if (input.mag > 0.001) {
    const control = p.onGround ? 1 : P.airControl;
    p.vx += input.dx * P.accel * control * dt;
    p.vz += input.dz * P.accel * control * dt;
    const sp = Math.hypot(p.vx, p.vz);
    if (sp > target) {
      const s = target / sp;
      p.vx *= s;
      p.vz *= s;
    }
  } else {
    const fr = Math.max(0, 1 - P.friction * dt);
    p.vx *= fr;
    p.vz *= fr;
  }

  p.vy += P.gravity * dt;
  if (input.jump && p.onGround) {
    p.vy = P.jumpVel;
    p.onGround = false;
  }

  const ox = p.x, oz = p.z;
  p.x += p.vx * dt;
  p.z += p.vz * dt;
  p.y += p.vy * dt;

  if (p.y <= 0 && p.vy <= 0) {
    p.y = 0;
    p.vy = 0;
    p.onGround = true;
  }

  const r = slideCircle(map, ox, oz, p.x, p.z, P.radius);
  p.x = r.x;
  p.z = r.z;
  return p;
}

/* Velocidade horizontal atual. */
export function speed2D(p) {
  return Math.hypot(p.vx, p.vz);
}

export default { stepPlayer, speed2D };

