/* weapons-core.js — matemática pura de armas: dano, splash falloff, spread,
 * cooldown, munição. Puro e testável (sem Three.js, sem window).
 */
import { C } from './constants.js';

/* Dano de splash com falloff linear: dmg*(1 - d/radius) + 1, mínimo 1. */
export function splashDamage(w, centerDist, radius = C.WEAPONS.rocket.splash) {
  if (centerDist >= radius) return 1;
  return w.damage * (1 - centerDist / radius) + 1;
}

/* Dano de splash aplicado ao próprio jogador (fração selfDamage). */
export function selfSplashDamage(w, centerDist) {
  return splashDamage(w, centerDist) * w.selfDamage;
}

/* Offset angular de spread dentro de [-spread, spread] em dois eixos. */
export function spreadOffset(spread) {
  return {
    a: (Math.random() * 2 - 1) * spread,
    b: (Math.random() * 2 - 1) * spread,
  };
}

/* Dispersão efetiva do chaingun: base + crescimento por tiro contínuo. */
export function chaingunSpread(base, spin) {
  return base + spin * C.WEAPONS.chaingun.spreadGrow;
}

/* Cooldown pronto? */
export function fireReady(w, sinceLast) {
  return sinceLast >= w.rate;
}

/* Pode disparar? Pistola é infinita; demais exigem munição. */
export function canFire(w, ammo) {
  if (w.ammoType === 'pistol') return true;
  return (ammo[w.ammoType] || 0) > 0;
}

/* Consome munição (imutável — retorna novo objeto). */
export function consumeAmmo(w, ammo) {
  if (w.ammoType === 'pistol') return ammo;
  const t = w.ammoType;
  return { ...ammo, [t]: Math.max(0, (ammo[t] || 0) - (w.ammoPerShot || 1)) };
}

/* Coleta munição com teto. Retorna { ammo, gained }. */
export function pickupAmmo(type, ammo, amount, max) {
  const before = ammo[type] || 0;
  const after = Math.min(max, before + amount);
  return { ammo: { ...ammo, [type]: after }, gained: after - before };
}

/* Dano de hitscan do zombie (3-8). */
export function zombieDamage() {
  const z = C.ENEMIES.zombie;
  return z.damageMin + Math.random() * (z.damageMax - z.damageMin);
}

export default {
  splashDamage, selfSplashDamage, spreadOffset, chaingunSpread,
  fireReady, canFire, consumeAmmo, pickupAmmo, zombieDamage,
};

