import test from 'node:test';
import assert from 'node:assert/strict';
import { moveVec, slideCircle, circleFree } from '../js/move.js';
import { makeMap } from '../js/map.js';

test('yaw=0: W anda -Z, D anda +X', () => {
  const f = moveVec(0, 0, -1);   // W (frente local)
  const r = moveVec(0, 1, 0);    // D (direita local)
  assert.ok(Math.abs(f.x - 0) < 1e-9 && Math.abs(f.z + 1) < 1e-9, `frente esperado (0,-1), got (${f.x},${f.z})`);
  assert.ok(Math.abs(r.x - 1) < 1e-9 && Math.abs(r.z - 0) < 1e-9, `direita esperado (1,0), got (${r.x},${r.z})`);
});

test('yaw=PI/2: W anda -X, D anda -Z (rotação correta, sem espelhamento)', () => {
  const f = moveVec(Math.PI / 2, 0, -1);
  const r = moveVec(Math.PI / 2, 1, 0);
  assert.ok(Math.abs(f.x + 1) < 1e-9 && Math.abs(f.z - 0) < 1e-9, `frente esperado (-1,0), got (${f.x},${f.z})`);
  assert.ok(Math.abs(r.x - 0) < 1e-9 && Math.abs(r.z + 1) < 1e-9, `direita esperado (0,-1), got (${r.x},${r.z})`);
});

test('yaw=PI: W anda +Z (volta ao ponto de partida em 2 passos)', () => {
  const f = moveVec(Math.PI, 0, -1);
  assert.ok(Math.abs(f.x - 0) < 1e-9 && Math.abs(f.z - 1) < 1e-9, `frente esperado (0,1), got (${f.x},${f.z})`);
});

test('yaw=-PI/2: W anda +X (leste — direção do spawn no salão)', () => {
  const f = moveVec(-Math.PI / 2, 0, -1);
  assert.ok(Math.abs(f.x - 1) < 1e-9 && Math.abs(f.z - 0) < 1e-9, `frente esperado (1,0), got (${f.x},${f.z})`);
});

test('diagonal (W+D): moveVec é linear puro, NÃO normaliza — normalização é do player (mul)', () => {
  const m = moveVec(0, 1, -1);
  assert.ok(Math.abs(m.x - 1) < 1e-9 && Math.abs(m.z + 1) < 1e-9, `esperado (1,-1), got (${m.x},${m.z})`);
  assert.ok(Math.abs(Math.hypot(m.x, m.z) - Math.SQRT2) < 1e-9, 'comprimento preservado = sqrt(2)');
  const s = 1 / Math.hypot(m.x, m.z);
  assert.ok(Math.abs(m.x * s - Math.SQRT1_2) < 1e-9 && Math.abs(m.z * s + Math.SQRT1_2) < 1e-9, 'normalizado daria (0.707,-0.707)');
});

test('rotação inversa: yaw=-yaw desfaz', () => {
  const a = moveVec(0.7, 0.3, -0.8);
  const b = moveVec(-0.7, a.x, a.z);
  assert.ok(Math.abs(b.x - 0.3) < 1e-9 && Math.abs(b.z + 0.8) < 1e-9, `inversa esperado (0.3,-0.8), got (${b.x},${b.z})`);
});

