import test from 'node:test';
import assert from 'node:assert/strict';
import { C } from '../js/constants.js';
import {
  splashDamage, selfSplashDamage, spreadOffset, chaingunSpread,
  fireReady, canFire, consumeAmmo, pickupAmmo, zombieDamage,
} from '../js/weapons-core.js';

test('splash falloff: dmg*(1-d/radius)+1 com mínimo 1', () => {
  const w = C.WEAPONS.rocket;
  assert.ok(Math.abs(splashDamage(w, 0) - (w.damage + 1)) < 1e-9, 'centro = dmg+1');
  assert.ok(Math.abs(splashDamage(w, w.splash) - 1) < 1e-9, 'borda = 1');
  assert.ok(Math.abs(splashDamage(w, w.splash / 2) - (w.damage * 0.5 + 1)) < 1e-9, 'meio = dmg/2+1');
  assert.equal(splashDamage(w, w.splash * 2), 1, 'fora do raio = 1');
  // monotônico decrescente
  let prev = Infinity;
  for (let d = 0; d <= w.splash + 0.5; d += 0.25) {
    const v = splashDamage(w, d);
    assert.ok(v <= prev + 1e-9, `falloff deve ser não-crescente em d=${d}`);
    prev = v;
  }
});

test('self splash: aplica fração selfDamage', () => {
  const w = C.WEAPONS.rocket;
  const d = selfSplashDamage(w, 0);
  assert.ok(Math.abs(d - (w.damage + 1) * w.selfDamage) < 1e-9, 'auto-dano = 0.5x');
});

test('spread: offsets dentro de [-spread, spread]', () => {
  for (let i = 0; i < 1000; i++) {
    const { a, b } = spreadOffset(0.08);
    assert.ok(a >= -0.08 && a <= 0.08, `a=${a} fora do intervalo`);
    assert.ok(b >= -0.08 && b <= 0.08, `b=${b} fora do intervalo`);
  }
});

test('chaingun spread cresce com o spin', () => {
  const base = C.WEAPONS.chaingun.spread;
  assert.ok(chaingunSpread(base, 0) === base, 'spin 0 = base');
  assert.ok(chaingunSpread(base, 10) > base, 'spin alto aumenta spread');
});

test('cooldown gating: fireReady respeita a cadência', () => {
  const pistol = C.WEAPONS.pistol;
  assert.equal(fireReady(pistol, 0.1), false, 'abaixo da cadência');
  assert.equal(fireReady(pistol, 0.3), true, 'na cadência exata');
  assert.equal(fireReady(pistol, 0.5), true, 'acima da cadência');
});

test('canFire: pistola infinita, demais exigem munição', () => {
  const pistol = C.WEAPONS.pistol;
  const shotgun = C.WEAPONS.shotgun;
  assert.equal(canFire(pistol, {}), true, 'pistola sempre dispara');
  assert.equal(canFire(shotgun, { shell: 0 }), false, 'sem munição');
  assert.equal(canFire(shotgun, { shell: 1 }), true, 'com munição');
});

test('consumeAmmo: decrementa e não vai abaixo de zero', () => {
  const shotgun = C.WEAPONS.shotgun;
  const chaingun = C.WEAPONS.chaingun;
  const a1 = consumeAmmo(shotgun, { shell: 12 });
  assert.equal(a1.shell, 11, 'shotgun consome 1');
  const a2 = consumeAmmo(chaingun, { bullet: 0 });
  assert.equal(a2.bullet, 0, 'não negativa');
  const a3 = consumeAmmo(C.WEAPONS.pistol, { shell: 5 });
  assert.equal(a3.shell, 5, 'pistola não consome');
});

test('pickupAmmo: coleta com teto e reporta ganho', () => {
  const shotgun = C.WEAPONS.shotgun;
  const r1 = pickupAmmo('shell', { shell: 30 }, 8, shotgun.ammoMax);
  assert.equal(r1.ammo.shell, 32, 'teto respeitado');
  assert.equal(r1.gained, 2, 'ganho limitado pelo teto');
  const r2 = pickupAmmo('bullet', { bullet: 0 }, 40, C.WEAPONS.chaingun.ammoMax);
  assert.equal(r2.ammo.bullet, 40);
  assert.equal(r2.gained, 40);
});

