import test from 'node:test';
import assert from 'node:assert/strict';
import { C } from '../js/constants.js';
import { stepPlayer, speed2D } from '../js/physics.js';
import { makeMap } from '../js/map.js';

const OPEN_MAP = [
  '##########',
  '#........#',
  '#........#',
  '#........#',
  '#........#',
  '#........#',
  '#........#',
  '#........#',
  '#........#',
  '##########',
];

const WALL_MAP = [
  '##########',
  '#........#',
  '#........#',
  '#...####.#',
  '#........#',
  '#........#',
  '#........#',
  '#........#',
  '#........#',
  '##########',
];

function freshPlayer(x = 5, z = 5) {
  return { x, y: 0, z, vx: 0, vy: 0, vz: 0, onGround: true };
}

test('aceleração atinge a velocidade máxima (walk 7) e não a ultrapassa', () => {
  const map = makeMap(OPEN_MAP);
  const p = freshPlayer();
  const input = { dx: 1, dz: 0, mag: 1, run: false, jump: false };
  let max = 0;
  for (let i = 0; i < 300; i++) {
    stepPlayer(map, p, input, 1 / 60);
    max = Math.max(max, speed2D(p));
  }
  assert.ok(Math.abs(speed2D(p) - C.PLAYER.walk) < 0.01, `velocidade final ${speed2D(p)} != walk ${C.PLAYER.walk}`);
  assert.ok(max <= C.PLAYER.walk + 0.01, `nunca ultrapassa walk (max ${max})`);
});

test('run (Shift) atinge 11 u/s', () => {
  const map = makeMap(OPEN_MAP);
  const p = freshPlayer();
  const input = { dx: 1, dz: 0, mag: 1, run: true, jump: false };
  for (let i = 0; i < 300; i++) stepPlayer(map, p, input, 1 / 60);
  assert.ok(Math.abs(speed2D(p) - C.PLAYER.run) < 0.01, `velocidade final ${speed2D(p)} != run ${C.PLAYER.run}`);
});

test('gravidade integra: vy decresce e y cai', () => {
  const map = makeMap(OPEN_MAP);
  const p = { x: 5, y: 2, z: 5, vx: 0, vy: 0, vz: 0, onGround: false };
  const dt = 1 / 60;
  stepPlayer(map, p, { dx: 0, dz: 0, mag: 0, run: false, jump: false }, dt);
  assert.ok(Math.abs(p.vy - C.PLAYER.gravity * dt) < 1e-9, `vy=${p.vy}, esperado ${C.PLAYER.gravity * dt}`);
  assert.ok(p.y < 2, `y deveria cair, got ${p.y}`);
});

test('pulo: arco sobe e desce, volta ao chão', () => {
  const map = makeMap(OPEN_MAP);
  const p = freshPlayer();
  stepPlayer(map, p, { dx: 0, dz: 0, mag: 0, run: false, jump: true }, 1 / 60);
  assert.ok(Math.abs(p.vy - C.PLAYER.jumpVel) < 1e-9, `vy inicial ${p.vy} != jumpVel`);
  let maxY = 0;
  let steps = 0;
  while (!p.onGround && steps < 600) {
    stepPlayer(map, p, { dx: 0, dz: 0, mag: 0, run: false, jump: false }, 1 / 60);
    maxY = Math.max(maxY, p.y);
    steps++;
  }
  assert.ok(maxY > 1.0, `altura máxima ${maxY} — pulo fraco demais`);
  assert.ok(maxY < 1.5, `altura máxima ${maxY} — pulo alto demais (esperado ~1.29)`);
  assert.equal(p.onGround, true, 'deve voltar ao chão');
});

test('atrito: velocidade decai monotonicamente sem input', () => {
  const map = makeMap(OPEN_MAP);
  const p = { x: 5, y: 0, z: 5, vx: 5, vy: 0, vz: 0, onGround: true };
  let prev = 5;
  for (let i = 0; i < 60; i++) {
    stepPlayer(map, p, { dx: 0, dz: 0, mag: 0, run: false, jump: false }, 1 / 60);
    const s = speed2D(p);
    assert.ok(s <= prev + 1e-9, `atrito deve decair (${s} > ${prev})`);
    prev = s;
  }
  assert.ok(speed2D(p) < 0.01, `após 1s a velocidade deve ser ~0, got ${speed2D(p)}`);
});

test('wall slide: jogador desliza ao longo da parede (X avança, Z bloqueado)', () => {
  const map = makeMap(WALL_MAP);
  const p = freshPlayer(2.5, 2.5);
  const input = { dx: Math.SQRT1_2, dz: -Math.SQRT1_2, mag: 1, run: false, jump: false };
  for (let i = 0; i < 600; i++) stepPlayer(map, p, input, 1 / 60);
  // parede da linha 3 (cols 4-7) bloqueia Z em ~4.5; X desliza até a parede leste
  assert.ok(p.z > 4.4 && p.z < 4.6, `Z deveria parar em ~4.5, got ${p.z}`);
  assert.ok(p.x > 7.5, `X deveria deslizar para leste, got ${p.x}`);
});

